        protected bool CanFinalizarAuditoria
        {
            get
            {
                // Obtener todos los hallazgos de la auditoría que no están cancelados
                var hallazgosNoCancelados = Resultados.SelectMany(r => r.Hallazgos).Where(h => h.Estatus != TipoEstatus.Cancelado).ToList();

