                var hallazgosFinalizados = hallazgosNoCancelados.Count(h => h.Estatus == TipoEstatus.Finalizado);

                return Estatus == TipoEstatus.EjecucionPDCA && !IsAuditado && hallazgosNoCancelados.Count() > 0 && hallazgosNoCancelados.Count() == hallazgosFinalizados;
