/// <summary>
    /// Rellena los sub-ítems del menú "Enviar Ticket" con los departamentos
    /// que atienden tickets, aplicando las restricciones de negocio
    /// (Inteligencia Empresarial, ticket principal, etc.).
    /// </summary>
    private void LlenarItemsEnviarTicketItem(TicketComputo ticket)
    {
        _enviarTicketItem.Items.Clear();

        var departamentos = ObjectSpace.Session().Query<Departamento>()
            .Where(w => w.AtiendeTickets)
            .ToList();

        foreach (var depto in departamentos)
        {
            if (depto.Clave == ClaveDepartamentos.InteligenciaEmpresarial
                && !ticket.PuedeVerDepartamentoInteligencia)
                continue;

            if (ticket.EsTicketPrincipal && depto.Clave != ClaveDepartamentos.Soporte)
                continue;

            _enviarTicketItem.Items.Add(ReyOneActionHelper.CreateChoiceAction(
                depto.Oid.ToString(), depto.Nombre, "MenuBar_Prev",
                "Envía el elemento seleccionado al departamento."));
        }
    }

