/// <summary>
    /// Valida si será permitido cancelar la Programacion de pago
    /// </summary>
    [Browsable(false), NonPersistent]
    private bool IsCancelable
    {
        get
        {
            if (Session.IsNewObject(this))
                return false;

            if (Estatus.In(TipoEstatus.Cancelado, TipoEstatus.Finalizado))
                return false;


            //Valida días permitidos.
            var max = DataManager.GetVariableSistema<double>(Computo.Constants.VariableSistemaKey.MaxDiasPermitidosCancelarProgramacionPago, Session, "INDICA LOS DÍAS PERMITIDOS PARA PODER CANCELAR PROGRAMACIONES DE PAGO", TipoDato.Double, "1");

            //Valida solo la fecha actual con la fecha permitida
            if (DataHelper.ServerDateTime(Session).Date > (Fecha.AddDays(max)).Date)
                return false;

            return true;
        }
    }
