/// <summary>
    /// Valida si el Flujo de Trabajo correspondiente al
    /// Ticket ha sido completado.
    /// </summary>
    [Browsable(false)]
    internal bool IsFlujoAsignadoCompleto
    {
        get
        {
            if (FlujoTrabajoAsignado != null)
            {
                var existeFlujo = false;
                if (EsTicketPrincipal)
                {
                    var flujoAsig = TicketComputoFlujoTrabajo.Where(d => d.Oid == FlujoTrabajoAsignado.Oid).FirstOrDefault();
                    if (flujoAsig != null)
                        existeFlujo = true;

                    if (flujoAsig?.TipoFinalizacionFlujo is null)
                        return false;
                }

                else if (TicketDependiente != null)
                {
                    var flujoSubtkt = TicketDependiente.TicketComputoFlujoTrabajo.Where(d => d.Oid == FlujoTrabajoAsignado.Oid).FirstOrDefault();
                    if (flujoSubtkt != null)
                        existeFlujo = true;

                    if (flujoSubtkt?.TipoFinalizacionFlujo is null)
                        return false;
                }

                if (!existeFlujo)
                    throw new UserFriendlyException("No se encontro el flujo de trabajo asignado al ticket de cómputo");
            }

            return true;
        }
    }
