        {
            var space = Application.CreateObjectSpace(typeof(PagoContrato));
            var pago = RecordHelper.GetCurrentObject<PagoContrato>(space, View, e.CurrentObject);
            var motivoCancelacion = space.CreateObject<MotivoCancelacionPago>();

