/// <summary>
    /// Obtiene o establece la orden de compra.
    /// </summary>
    [Persistent("fk_orden_compra"), XafDisplayName("Orden de Compra"), ImmediatePostData]
    [Appearance("A_RecepcionComputo.OrdenCompra.Deshabilita", Enabled = false, Criteria = nameof(EsTipoOrdenCompra))]
    [RuleRequiredField("R_RecepcionComputo.OrdenCompra.Requerido", DefaultContexts.Save, "La Orden de compra es requerida.", TargetCriteria = "!EsTipoOrdenCompra")]
    [DataSourceCriteriaProperty(nameof(FiltroOrdenCompra))]
    public OrdenCompra OrdenCompra
    {
        get => GetProperty<OrdenCompra>();
        set => SetProperty(value, () =>
        {
            if (RecepcionDetalle.Any())
                Session.Delete(RecepcionDetalle);

            Observaciones = null;
            NumeroPlano = null;

            if (value is null)
                return;

            Observaciones = value.Observaciones;
            NumeroPlano = value.NumeroPlano;

            //barre los detalles de la orden de compra
            foreach (var item in value.Detalles.Where(d => d.Estatus != TipoEstatus.Cancelado && d.Estatus != TipoEstatus.Atendido))
            {
                var _producto = Session.Query<Producto>().FirstOrDefault(p => p.Oid == new Guid(item.ProductoLigero.ProductoID) && p.Estatus == TipoEstatus.Activo);
                var _recepcionComputoDetalle = new RecepcionComputoDetalle(Session) { };
                var _precioUnitario = 0M;
                var _iva = 0M;

                _recepcionComputoDetalle.OrdenCompraDetalle = item;
                _recepcionComputoDetalle.ProductoSolicitado = _producto;
                _recepcionComputoDetalle.Producto = _producto;
                _recepcionComputoDetalle.UnidadMedida = item.UnidadMedida;
                _recepcionComputoDetalle.CantidadSolicitada = item.CantidadSolicitada - item.CantidadAtendida;
                _recepcionComputoDetalle.NumeroPlano = NumeroPlano;
                _recepcionComputoDetalle.Observaciones = item.Observaciones;
                _recepcionComputoDetalle.Proveedor = item.Master.Proveedor;
                _recepcionComputoDetalle.EmpresaCompra = item.Master.EmpresaFactura;
                _recepcionComputoDetalle.CantidadRecibida = item.CantidadSolicitada - item.CantidadAtendida;
                //_recepcionComputoDetalle.CantidadSurtida = item.CantidadSolicitada - item.CantidadAtendida;
                _recepcionComputoDetalle.TipoGastoDetalleTI = item.TipoGastoDetalleTI;
                //_recepcionComputoDetalle.PrecioNeto = (item.PrecioUnitario + ((int)item.TasaIva / 100M)) * item.Master.TipoCambio;

                var _conceptoGasto = Session.Query<Producto>().Where(x => x.Oid.ToString() == _producto.Oid.ToString()).Select(x => x.Subrama.ConceptoGastoDetalleTI).FirstOrDefault();
                if (_conceptoGasto != null)
                    _recepcionComputoDetalle.TipoGastoDetalleTI = _conceptoGasto;

                //valida moneda extrangera para pasarla a moneda nacional
                if (Convert.ToBoolean(value.TipoMoneda.Extranjera))
                {
                    var TipoCambio = 0M;

                    if (value.TipoMoneda.Clave == "USD")
                    {
                        var TipoCambioMinimo = DataManager.GetVariableSistema<decimal>(Computo.Constants.VariableSistemaKey.TipoCambioMinimoDolar, Session);
                        if (value.TipoCambio >= TipoCambioMinimo)
                            TipoCambio = value.TipoCambio;
                        else
                            TipoCambio = value.MonedaHistorialTipoCambio.TipoCambio;

                    }
                    else
                        TipoCambio = value.MonedaHistorialTipoCambio.TipoCambio;

                    //Obtiene el tipo de cambio del catalogo de monedas.
                    //Tarea actualiza desde la bolsa de méxico.
                    _precioUnitario = item.PrecioUnitario * TipoCambio;
                    //calcula el iva en moneda nacional
                    _iva = _precioUnitario * ((int)item.TasaIva / 100M);

                    _precioUnitario = _precioUnitario + _iva;
                }
                else//toma el precio como moneda nacinal
                {
                    _iva = item.PrecioUnitario * ((int)item.TasaIva / 100M);
                    _precioUnitario = item.PrecioUnitario + _iva;
                }

                _recepcionComputoDetalle.PrecioNeto = _recepcionComputoDetalle.UnidadMedida == _recepcionComputoDetalle.Producto.UnidadMedidaCompra ?
                                                        (_precioUnitario / _recepcionComputoDetalle.Producto.CantidadPorUnidadCompra) :
                                                        _precioUnitario;

                _recepcionComputoDetalle.UbicacionComputo = Almacen.ObtenerUbicacionDefaultEntrada(_producto);
                _recepcionComputoDetalle.TipoInventario = item.Master.TipoInventario;

                RecepcionDetalle.Add(_recepcionComputoDetalle);
            }
            ForcePropertyChanged(() => Total);
        });
    }

