/// <summary>
        /// Obtiene criteria para limitar ordenes de compra.
        /// Central de compras asigndas al usuario.
        /// </summary>
        [Browsable(false)]
        public virtual CriteriaOperator CriteriaOrdenesCompras
        {
            get
            {
                var criteria = new GroupOperator(GroupOperatorType.And);

                // By Estatus
                criteria.Operands.Add(CriteriaOperator.Parse("[Estatus] = ##Enum#REYMA.XAFR1PV.Base.TipoEstatus,Activo# OR [Estatus] = ##Enum#REYMA.XAFR1PV.Base.TipoEstatus,Parcial#"));

                // By Centrales de Compras
                //criteria.Operands.Add(CriteriaOperator.Parse("[CentralCompra.Oid] = '@This.CentralCompra.Oid'"));
                var userPurchaseCentrals = Session.CurrentUser().AllowedPurchaseCentrals(Session);
                var defaultCriteria = StringFunctionFormat.ObtenerCondicionIn(userPurchaseCentrals);
                criteria.Operands.Add(CriteriaOperator.Parse($"[CentralCompra.Oid] IN({defaultCriteria})"));

                if (OrdenesCompras.Count > 0)
                {
                    // By Moneda
                    criteria.Operands.Add(CriteriaOperator.Parse("[TipoMoneda.Oid] = '@This.Moneda.Oid'"));

                    // By Proveedor
                    criteria.Operands.Add(CriteriaOperator.Parse("[Proveedor.Oid] = '@This.Proveedor.Oid'"));

                    //By Central Compras
                    criteria.Operands.Add(CriteriaOperator.Parse("[CentralCompra.Oid] = '@This.CentralCompra.Oid'"));

                    // Exclude added
                    criteria.Operands.Add(CriteriaOperator.Parse($"NOT [Oid] IN ({string.Join(", ", OrdenesCompras.Select(d => $"'{d.Oid}'").ToList())})"));
                }

                if (RequiereAutorizaciones)
                {
                    //criteria.Operands.Add(CriteriaOperator.Parse($"EstatusAutorizacion = ##Enum#REYMA.XAFR1PV.Compras.Compras.BO.EstatusAutorizacion,Autorizado# Or IsNull([EstatusAutorizacion]) "));
                    //criteria.Operands.Add(CriteriaOperator.Parse($"AutorizadoresOC[EstatusAutorizacion = ##Enum#REYMA.XAFR1PV.Compras.Compras.BO.EstatusAutorizacionAutorizadores,Autorizado#].Count() = AutorizadoresOC.Count()"));

                    var oidOcDentro = Session.Query<OrdenCompra>().
                        Where(x => userPurchaseCentrals.Contains(x.CentralCompra.Oid) &&
                            (x.Estatus == TipoEstatus.Activo || x.Estatus == TipoEstatus.Parcial) &&
                            x.EstatusAutorizacion == EstatusAutorizacion.Autorizado &&
                            x.AutorizadoresOC.All(d => d.EstatusAutorizacion == EstatusAutorizacionAutorizadores.Autorizado) &&
                            x.Fecha.Date >= CentralCompra.FechaValidaAutorizacion.Date).
                        Select(x => x.Oid);

                    var oidOcFuera = Session.Query<OrdenCompra>().
                        Where(x => userPurchaseCentrals.Contains(x.CentralCompra.Oid) &&
                            (x.Estatus == TipoEstatus.Activo || x.Estatus == TipoEstatus.Parcial) &&
                            x.Fecha.Date < CentralCompra.FechaValidaAutorizacion.Date).
                        Select(x => x.Oid);

                    var oidsUnion = oidOcDentro.Union(oidOcFuera);
                    var oidsOC = StringFunctionFormat.ObtenerCondicionIn(oidsUnion);
                    criteria.Operands.Add(CriteriaOperator.Parse($"[Oid] IN({oidsOC})"));
                }

                // With detalles pendientes
                criteria.Operands.Add(CriteriaOperator.Parse("Detalles[Estatus = ##Enum#REYMA.XAFR1PV.Base.TipoEstatus,Activo# OR Estatus = ##Enum#REYMA.XAFR1PV.Base.TipoEstatus,Parcial#].Sum(CantidadSolicitada - CantidadAtendida) > 0"));

                return criteria;
            }
        }

