/// <summary>
    /// Realiza el cierre del ticket desde una entrega de consumible.
    /// </summary>
    /// <param name="personaCierra"></param>
    internal void RealizaCierreTicketEntregaConsumible(Empleado personaCierra)
    {
        //Get tipo servicio sistemas
        var tipoServicioSistemas = Session.Query<TipoServicioComputo>().FirstOrDefault(i => i.Clave == "TON");

        if (tipoServicioSistemas is null)
            throw new UserFriendlyException("Error, tipo de servicio TONER no encontrado, contacte a sistemas.");

        var descripcionActividad = "TICKET ATENDIDO; FAVOR DE PASAR AL ALMACÉN PARA LA ENTREGA DEL CONSUMIBLE.";

        Actividad.Add(new TicketComputoActividad(Session)
        {
            DescripcionActividad = descripcionActividad
        });

        //Generales ticket.
        Motivo = descripcionActividad;
        Estatus = TipoEstatus.Atendido;
        FechaCierre = DataHelper.ServerDateTime(Session);
        PersonalCierra = personaCierra;
        TipoServicioSistemas = tipoServicioSistemas;

        //auditoria
        var _auditoria = AuditHelper.Add<TicketComputo>(Session, this, TipoEstatus.Atendido.ToString(), "TICKET ATENDIDO DESDE UNA ENTREGA DE CONSUMIBLE.");
        Bitacora.Add(_auditoria);
    }

