public void AfterEstatusChangeLogic(string motivo, ReymaFileData adjunto, TipoServicioComputo tipoServicio, ModuloSistema moduloSistema = null)
    {
        if (Actividad.Count == 0)//No hay actividades asi que insertamos el texto en la actividad tambien para que no se quede vacio el campo
        {
            Actividad.Add(new TicketComputoActividad(Session)
            {
                CapturadoPor = this.Employee(Session),
                Fecha = DataHelper.ServerDateTimeCST(Session),
                DescripcionActividad = motivo,
                Observaciones = "ACTIVIDAD AUTOMATICA POR ATENCIÓN DE TICKET.",
            });
        }

        Motivo = motivo;
        if (Motivo.Length >= 499)
            Motivo = Motivo.Substring(0, 499);

        DocumentoMotivo = adjunto;
        if (DocumentoMotivo?.Content != null)
            AgregarDocumento(DocumentoMotivo, "EVIDENCIA CIERRE DE TICKET CON DOCUMENTO ADJUNTO");

        TipoServicioSistemas = tipoServicio;
        EstatusInterno = TipoEstatusInterno.Finalizado;
        PersonalCierra = this.Employee(Session);
        FechaCierre = DataHelper.ServerDateTimeCST(Session);
        AuditHelper.Add(Session, this, "ATENDIDO", $"TICKET ATENDIDO POR: {this.Employee(Session).NombreCompleto}");

        if (PersonalAsignado is null)
            PersonalAsignado = PersonalCierra;
    }

