/// <summary>
    /// Valida las precondiciones de cierre (diagnóstico, subtickets) y
    /// aplica el estatus <see cref="TipoEstatus.Atendido"/> al ticket.
    /// </summary>
    private void CerrarTicketAction(SimpleActionExecuteEventArgs e)
    {
        var space = Application.CreateObjectSpace(typeof(TicketComputo));
        if (RecordHelper.GetCurrentObject(space, View, e.CurrentObject) is not TicketComputo ticket)
            return;

        if (!ticket.ValidaCerrarTicket()) return;

        var motivosSubtickets = ObtenerMotivosSubtickets(space, ticket);
        ApplyEstatus<IEstatus>(space, e, TipoEstatus.Atendido, motivosSubtickets);
    }

