/// <summary>
    /// Resuelve la lista de destinatarios para el correo del ticket, dependiendo de si el ticket tiene una asignación o no. Si el ticket tiene una asignación, se envía únicamente al personal asignado; de lo contrario, se envía al personal que reporta y a los correos relacionados configurados en el catálogo de cuentas de correo. Además, se incluyen en los destinatarios los correos relacionados específicos del email configurado para el proceso, evitando duplicados.
    /// </summary>
    /// <param name="ticket"></param>
    /// <param name="destinatarios"></param>
    /// <param name="email"></param>
    /// <returns></returns>
    private static List<MailAddress> ResolveTicketRecipients(
        TicketComputo ticket,
        List<(string nombre, string email, bool es_principal)> destinatarios,
        Email email)
    {
        var to = new List<MailAddress>();

        if (ticket.AsignacionComputo is not null)
        {
            var encargado = ticket.SolicitudCuentaCatalogo?.Encargado;
            encargado?.EmpleadoCuentasCorreo
                .Where(d => d.Estatus == TipoEstatus.Activo)
                .ForEach(d => to.Add(new MailAddress(d.Email, encargado.NombreCompleto)));
        }
        else
        {
            destinatarios
                .Where(d => !string.IsNullOrEmpty(d.email))
                .ForEach(d => to.Add(new MailAddress(d.email, d.nombre)));
        }

        email.EmailRelacionados
            .ForEach(p => to.Add(new MailAddress(p.CuentaRelacion, p.CuentaRelacion)));

        return to;
    }

