/// <summary>
    /// Obtiene los destinatarios del correo a partir del personal que reporta el ticket, asegurando que no haya correos duplicados entre el email directo del empleado y el email de catálogo de cuentas de correo. Si el ticket tiene una asignación, se omiten los destinatarios relacionados al personal que reporta y se envía únicamente al personal asignado para evitar notificaciones innecesarias.
    /// </summary>
    /// <param name="ticket"></param>
    /// <returns></returns>
    private static List<(string nombre, string email, bool es_principal)> GetDestinatariosDistinct(TicketComputo ticket) =>
        ticket.PersonalReporta
            .GetEmailEmpleado()
            .Concat(ticket.PersonalReporta.GetEmailCatalogoEmpleadoCuentaCorreo())
            .GroupBy(t => (t.Item1, t.Item2))
            .Select(g => g.First())
            .ToList();

