/// <summary>
    /// Envía la notificación de asignación interna de un Ticket al personal asignado.
    /// </summary>
    /// <param name="session">La <see cref="Session"/> activa.</param>
    /// <param name="ticket">El <see cref="TicketComputo"/> asignado.</param>
    /// <param name="tipoDocumento">Texto usado como título en el correo.</param>
    /// <returns><c>true</c> si el correo fue enviado; <c>false</c> en caso contrario.</returns>
    public static bool SendTicketAsignationNotification(
        Session session,
        TicketComputo ticket,
        string tipoDocumento = "Asignación de Ticket de Servicio")
    {
        ArgumentNullException.ThrowIfNull(session);
        ArgumentNullException.ThrowIfNull(ticket);

        var destinatarios = ticket.PersonalAsignado?.GetEmailEmpleado();
        if (destinatarios is not { Count: > 0 })
            return false;

        var email = ResolveEmailConfig(session, Constants.VariableSistemaKey.DefaultEmailModuloTicketAsignadoInterno);

        var recipients = destinatarios
            .Where(d => !string.IsNullOrEmpty(d.Email))
            .Select(d => new MailAddress(d.Email, d.Nombre))
            .ToList();

        var body = BuildAsignacionBody(ticket, email, tipoDocumento);
        var subject = BuildSubject(email.Asunto, tipoDocumento, ticket.Folio);
        var bodyWithSignature = AppendSignature(body, email, firmaNombre: null);

        Messenger.Default.Send(
            new SendMailMessage($"{tipoDocumento} {ticket.Folio}", email, recipients, subject, bodyWithSignature));

        return true;
    }

