/// <summary>
    /// Agrega al criterio los filtros de sucursal cuando el usuario tiene
    /// el permiso especial <c>AuhtTicketVerPorSucursal</c>.
    /// </summary>
    private void AgregarFiltroPorSucursal(GroupOperator criteria)
    {
        if (!View.ObjectSpace.Session().CurrentUser()
                .HasSpecialPermission(Computo.Constants.ClavePermisoEspecial.AuhtTicketVerPorSucursal))
            return;

        const string filterField = ".EmpleadoDeSucursal";
        var sucursalesUsuario = View.ObjectSpace.Session().CurrentUser()
                                    .AllowedTicketBranches(ObjectSpace.Session());

        if (sucursalesUsuario == null || !sucursalesUsuario.Any()) return;

        var joinedSucursales = StringFunctionFormat.ObtenerCondicionIn(sucursalesUsuario);

        criteria.Operands.Add(CriteriaOperator.Parse(
            $"{nameof(TicketComputo.PersonalRegistra)}{filterField}.Oid In ({joinedSucursales})"));
        criteria.Operands.Add(CriteriaOperator.Parse(
            $"{nameof(TicketComputo.PersonalReporta)}{filterField}.Oid In ({joinedSucursales})"));
        criteria.Operands.Add(CriteriaOperator.Parse(
            $"{nameof(TicketComputo.PersonalAsignado)}{filterField}.Oid In ({joinedSucursales})"));
    }

