    /// el permiso especial <c>AuthTicketVerDepto</c>.
    /// </summary>
    private void AgregarFiltroPorDepartamento(GroupOperator criteria, Empleado personal)
    {
        if (!View.ObjectSpace.Session().CurrentUser()
                .HasSpecialPermission(Computo.Constants.ClavePermisoEspecial.AuthTicketVerDepto))
            return;

        var deptoUsuario = personal.Departamento;
        if (deptoUsuario is null) return;

        const string deptoFilter = ".Departamento";

        criteria.Operands.Add(CriteriaOperator.Parse(
            $"{nameof(TicketComputo.PersonalRegistra)}{deptoFilter}.Oid = '{deptoUsuario.Oid}'"));
        criteria.Operands.Add(CriteriaOperator.Parse(
            $"{nameof(TicketComputo.PersonalReporta)}{deptoFilter}.Oid = '{deptoUsuario.Oid}'"));
        criteria.Operands.Add(CriteriaOperator.Parse(
            $"{nameof(TicketComputo.PersonalAsignado)}{deptoFilter}.Oid = '{deptoUsuario.Oid}'"));
    }

