/// <summary>
    /// Cancela todas las <see cref="AutorizacionGenerica"/> vinculadas a los
    /// diagnósticos activos del ticket.
    /// </summary>
    private static void CancelarAutorizacionesGenericas(IObjectSpace space, TicketComputo ticket)
    {
        var oidsActivos = space.Session().Query<ActivosDiagnosticos>()
            .Where(p => p.Estatus != TipoEstatus.Cancelado && p.Ticket.Oid == ticket.Oid)
            .Select(s => s.Oid)
            .ToList();

        if (!oidsActivos.Any()) return;

        space.Session().Query<AutorizacionGenerica>()
            .Where(p => p.Estatus != TipoEstatus.Cancelado
                     && oidsActivos.Contains(p.OidDocumento))
            .ForEach(a => a.Estatus = TipoEstatus.Cancelado);
    }

