/// <summary>
    /// Valida las reglas de negocio de una <see cref="TicketComputoAsignaciones"/>:
    /// RuleSet completo, personal asignado y tipo de servicio no transitorio.
    /// </summary>
    private void ValidaAsignacion(TicketComputoAsignaciones asignacion)
    {
        var validationResult = Validator.GetService(Application.ServiceProvider)
            .ValidateTarget(ObjectSpace, asignacion, DefaultContexts.Save);

        var firstError = validationResult.Results
            .Where(x => x.State == ValidationState.Invalid)
            .Select(x => x.ErrorMessage)
            .FirstOrDefault();

        if (firstError != null)
            throw new UserFriendlyException($"Error de validación: {firstError}");

        if (asignacion.PersonalAsignado is null)
            throw new UserFriendlyException("Debe seleccionar un personal para poder asignar el ticket");

        var ultAsignacion = ObjectSpace.Session().Query<TicketComputoAsignaciones>()
            .Where(a => a.Master.Oid == asignacion.Master.Oid && a.Estatus != TipoEstatus.Cancelado)
            .OrderByDescending(a => a.FechaUltimaAsignacion)
            .FirstOrDefault();

        if (ultAsignacion?.TipoServicioInterno?.Clave
            == TicketComputoAsignacionConstans.ClaveTipoServicioTransitorio)
            throw new UserFriendlyException(
                "No es posible realizar la asignación, el tipo de servicio no puede ser transitorio.");
    }

