/// <summary>
    /// Verifica todas las precondiciones de negocio antes de generar
    /// un mantenimiento correctivo desde el ticket.
    /// </summary>
    private static void ValidarPrecondicionesCentroServicio(TicketComputo ticket)
    {
        if (ticket.EstatusInterno != TipoEstatusInterno.Recibido || ticket.Estatus != TipoEstatus.Proceso)
            throw new UserFriendlyException(
                "Es necesario recibir el ticket para realizar el centro de servicio.");

        if (ticket.Diagnostico == null || !ticket.Diagnostico.Any(w => w.Estatus != TipoEstatus.Cancelado))
            throw new UserFriendlyException(
                "Es necesario registrar diagnostico para realizar el centro de servicio.");

        if (ticket.TipoServicio.EsActivo && ticket.Activo is null)
            throw new UserFriendlyException($"El ticket {ticket.Folio} requiere de un activo.");

        if (!ticket.IsPermiteCentroServicio)
            throw new UserFriendlyException(
                $"Es necesario la autorización digital para los diagnósticos relacionados al ticket {ticket.Folio}");

        if (ticket.Diagnostico
            .Where(w => w.Estatus != TipoEstatus.Cancelado)
            .Where(w => w.CausaRecoleccion.Clave == CatalogosEspeciales.ClaveCausaReasignacionEnSitio)
            .Any(a => a.Documento == null))
            throw new UserFriendlyException(
                "Los diagnosticos con causa 'Reasignación En Sitio' requieren de responsiva adjunta.");
    }

