private void CompletarAuditoria(object sender, SimpleActionExecuteEventArgs e)
        {
            try
            {
                // Obtener el objeto actual
                var auditoria = e.CurrentObject as BO.Procesos.Auditorias;

                // Guardar el Oid antes de modificar el objeto
                var auditoriaOid = auditoria.Oid;

                auditoria.Estatus = TipoEstatus.Completado;
                auditoria.FechaCompletado = DateTime.Now;

                if (ObjectSpace.IsModified)
                    ObjectSpace.CommitChanges();

                // Refrescar el ObjectSpace después de guardar
                ObjectSpace.Refresh();

                // Obtener el objeto actualizado después del refresh
                var auditoriaActualizada = ObjectSpace.GetObjectByKey<BO.Procesos.Auditorias>(auditoriaOid);

                // Envío de correo con los resultados
                MostrarModalEnvioCorreo(e, auditoriaActualizada);

                ActualizarCaptions();
            }
            catch (Exception ex)
            {
                ObjectSpace.ConfirmationRequired += (s, e) => e.ConfirmationResult = ConfirmationResult.Yes;

                ObjectSpace.Rollback();
                ObjectSpace.Refresh();
                Application.ShowViewStrategy.ShowMessage("Error al completar la auditoría: " + ex.Message, InformationType.Error);
            }
        }

