[DisableConcurrentExecution(5 * 60)]
    public void Execute()
    {
        try
        {
            _logger.LogInformation("Ejecutando envío correos de programación de pagos...");

            var space = _db.Provider.CreateObjectSpace();
            var fechaActual = DataHelper.ServerDateTime(space.Session());
            var diasEnvioCorreo = DataManager.GetVariableSistema<int>(Computo.Constants.VariableSistemaKey.DiasEnvioCorreoProgramacionPago, space.Session(), "INDICA LOS DÍAS PARA COMENZAR A ENVIAR CORREOS DE PROGRAMACIONES SIN PAGAR", TipoDato.Integer, "1");
            var programaciones = space.Session().Query<ProgramacionPago>().Where(prog => prog.Estatus == TipoEstatus.Programacion && prog.Fecha.AddDays(diasEnvioCorreo).Date <= fechaActual.Date && prog.EnviaNotificaciones);

            if (!programaciones.Any())
                return;

            //Envía los correos a cada programación designada.
            programaciones.ForEach(x => EnviarEmail(x));

            _logger.LogInformation(LoggingEvents.QUERY_ITEMS_FINISHED, "Enviar correos de programación de pagos ejecutado con éxito.");
            space.Dispose();
        }
        catch (Exception ex)
        {
            _logger.LogError(LoggingEvents.QUERY_ITEMS_EXCEPTION, ex.Message, ex);
        }
    }

