/// <summary>
    /// Valida que la orden de compra asignada se encuentro dentro del importe permitido
    /// </summary>
    [Browsable(false)]
    [RuleFromBoolProperty("RFB_PagoContrato.Monto_Pago_Valido", DefaultContexts.Save, "{MensajeError}")]
    public bool IsMontoPagoValido
    {
        get
        {
            if (Estatus.In(TipoEstatus.Cancelado, TipoEstatus.Finalizado))
                return true;

            var solicitudes = SolicitudesServicio.Where(d => d.Estatus != TipoEstatus.Cancelado);
            if (solicitudes.Any())
            {
                foreach (var item in solicitudes)
                {
                    //Monto del Proyecto en la Orden de Compra
                    var montOC = Math.Floor(item.OrdenCompra.SolicitudesServicio.Where(s => s.SolicitudServicioId == item.SolicitudServicioId).FirstOrDefault().Importe);

                    if (Math.Floor(item.Importe) > montOC + 1)
                    {
                        MensajeError = $"El Importe aplicado para la Solicitud de Servicio: #{item.SolicitudServicioFolio} de la O.C: #{item.OrdenCompra?.Folio} sobrepasa el saldo de ${montOC:0.00} disponible.";
                        return false;
                    }

                    //Monto de los pagos de esa Orden y ese proyecto
                    var solicitudesPagos = Session.Query<PagoContratoSolicitudServicio>().Where(s => s.Master.Estatus == TipoEstatus.Finalizado && s.OrdenCompra.Oid == item.OrdenCompra.Oid
                                                && s.SolicitudServicioId.Contains(item.SolicitudServicioId) && s.Master.Oid != Oid);
                    if (solicitudesPagos.Any())
                    {
                        var montoPagado = Math.Floor(solicitudesPagos.Sum(d => d.Importe));

                        if (montoPagado + Math.Floor(item.Importe) > montOC + 1)
                        {
                            MensajeError = $"El Importe aplicado para la Solicitud de Servicio: #{item.SolicitudServicioFolio} de la O.C: #{item.OrdenCompra?.Folio} " +
                                $"tiene pagos aplicados por: ${montoPagado:0.00} y sobrepasa el saldo actual de ${(montOC - montoPagado):0.00}.";

                            return false;
                        }
                    }

                    if (ProgramacionesOrdenesCompra.Where(p => p.Estatus != TipoEstatus.Cancelado && p.SolicitudServicioId == item.SolicitudServicioId).Count() > 0 && item.Importe == 0.00M)
                    {
                        MensajeError = $"El Importe aplicado para la Solicitud de Servicio: #{item.SolicitudServicioFolio} de la O.C: #{item.OrdenCompra?.Folio} no puede ser $0.00";
                        return false;
                    }
                }
            }

            if (ProgramacionesOrdenesCompra.Where(p => p.Estatus != TipoEstatus.Cancelado).Sum(p => p.Importe) > MontoPagar)
            {
                MensajeError = "El importe de las proyecciones es mayor que el monto total a pagar.";
                return false;
            }

            return true;
        }
    }

